fn solve(input: Vec<char>) -> Vec<char> {
    // Since input always contains exactly one lowercase letter, we can safely index into it.
    let c = input[0];
    // Check if the character is one of the five vowels
    if matches!(c, 'a' | 'e' | 'i' | 'o' | 'u') {
        "vowel".chars().collect()
    } else {
        "consonant".chars().collect()
    }
}

fn main() {
    // Example usage:
    let input = vec!['a'];
    let output = solve(input);
    assert_eq!(output, "vowel".chars().collect::<Vec<_>>());

    let input = vec!['z'];
    let output = solve(input);
    assert_eq!(output, "consonant".chars().collect::<Vec<_>>());

    println!("All tests passed!");
}